    },
    {
      "requirement_id": "KDH-104",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman damgalarının UTC formatında ve iç sistem saatinden üretildiği, denetim kayıtları oluşturularak ve değerler karşılaştırılarak test edilebilir."
    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim, değişiklik veya silme denemelerinin algılanması ve uyarı mekanizmasının çalışması, saldırı senaryoları simüle edilerek test edilebilir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
        "Test"
      ],
      "rationale": "Kimlik doğrulama bilgilerinin ekranda gizlenip gizlenmediği, kullanıcı arayüzü üzerinden girdi vererek ve ekran görüntüsü alarak gözlemlenebilir."
    },
    {
      "requirement_id": "KDH-107",
      "methods": [
        "Test"
      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi dolan oturumlarda yeniden kimlik doğrulama zorunluluğunun uygulanıp uygulanmadığı, senaryo bazlı testlerle doğrulanabilir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test"
      ],
      "rationale": "Veri iletiminin şifreli ve bütünlüğü korunan protokollerle (ör. TLS) gerçekleştiği, ağ trafiği yakalanarak ve sertifika/protokol kontrolü yapılarak test edilebilir."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz, bozuk veya beklenmedik girdilerin sistemin reddedip reddetmediği, çeşitli hata senaryoları ile test edilebilir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya genel bilgi verip vermediği ve detaylı logların yetkili personele mi gösterildiği, hata senaryoları tetiklenerek gözlemlenebilir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum sonu uyarısı, taslak kaydetme ve veri kaybı olmadan devam etme akışının çalışıp çalışmadığı, kullanıcı senaryoları ile test edilebilir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test"
      ],
      "rationale": "CAPTCHA kullanılmadığı, bot eşiği aşıldığında etkileşimsiz kanıt istendiği ve istisna durumlarında nesne tanıma sorgusu gösterildiği, farklı bot simülasyonları ile test edilebilir."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "Ödeme sonucunun yalnızca imzalı bildirimle kabul edildiği, belirsiz durumlarda 'ödeme bekliyor' durumunda tutulduğu ve sorgulama aralıklarının çalıştığı, KÖA entegrasyon senaryoları ile test edilebilir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı veya eksik alanlı e-Devlet belirteçlerinde oturumun sınırlı kipte açıldığı ve kişisel verilerin gizlendiği, farklı AAL düzeylerinde giriş yapılarak test edilebilir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresinin yalnızca şirket temsilcilerine uygulandığı, bildirimlerin gönderildiği ve ele geçirme kanıtında zorunlu değişikliğin tetiklendiği, hesap senaryoları ile test edilebilir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
